import sys

def solve(n, s, arr):
    current_sum = sum(arr)
    operations = 0

    while current_sum != s:
        if current_sum < s:
            if not arr or arr[-1] == 0:
                return -1
            current_sum += arr.pop()
        else:
            if not arr or arr[0] == 0:
                return -1
            current_sum -= arr.pop(0)
        operations += 1

